if(PHP_SAPI!=='cli')exit(2);require dirname(__DIR__).'/resources/require.php';$db=$database->db;$schema='menu115_'.bin2hex(random_bytes(6));$n=0;$ok=static function($v,$m)use(&$n){if(!$v)throw new RuntimeException($m);$n++;};$q=static function($s,$p=[])use($db){$s=$db->prepare($s);$s->execute($p);return$s;};
