foreach(['v_menu_item_groups','v_menu_languages','v_menu_items']as$t)$q('delete from '.$t.' where menu_item_uuid=?',[$id]);$fresh=uuid();$q("insert into v_menu_items(menu_item_uuid,menu_uuid,uuid,menu_item_title,menu_item_link)values(?,?,?,'My PBX','/app/pbx_staff/')",[$fresh,$menu,'c493b34d-1ca4-4a1c-8dc3-129662029e61']);$q("insert into v_menu_languages(menu_language_uuid,menu_uuid,menu_item_uuid,menu_language,menu_item_title)values(?,?,?,'en-us','Fresh custom label')",[uuid(),$menu,$fresh]);$db->exec($sql);$ok((int)$q("select count(*) from v_menu_items where menu_item_link='/app/pbx_staff/'")->fetchColumn()===1,'Fresh installer duplicated its imported menu');$ok($q('select menu_item_title from v_menu_languages where menu_item_uuid=? and menu_language=?',[$fresh,'en-us'])->fetchColumn()==='Fresh custom label','Fresh initializer overwrote existing label');$ok((int)$q('select count(*) from v_menu_item_groups where menu_item_uuid=?',[$fresh])->fetchColumn()===1,'Fresh staff group points to a different menu row');echo "PASS: $n actual staff menu SQL upgrade/fresh/label controls\n";
}finally{if($db->inTransaction())$db->rollBack();$db->exec('set search_path to public');$db->exec('drop schema if exists '.$schema.' cascade');}
